CREATE TABLE `all_types` (
  `id` int(11) NOT NULL,
  `c_tinyint` tinyint(4) DEFAULT NULL,
  `c_tinyint_u` tinyint(3) unsigned DEFAULT NULL,
  `c_smallint` smallint(6) DEFAULT NULL,
  `c_smallint_u` smallint(5) unsigned DEFAULT NULL,
  `c_mediumint` mediumint(9) DEFAULT NULL,
  `c_mediumint_u` mediumint(8) unsigned DEFAULT NULL,
  `c_int` int(11) DEFAULT NULL,
  `c_int_u` int(10) unsigned DEFAULT NULL,
  `c_bigint` bigint(20) DEFAULT NULL,
  `c_bigint_u` bigint(20) unsigned DEFAULT NULL,
  `c_decimal` decimal(40,10) DEFAULT NULL,
  `c_float` float DEFAULT NULL,
  `c_double` double DEFAULT NULL,
  `c_bit` bit(8) DEFAULT NULL,
  `c_date` date DEFAULT NULL,
  `c_datetime` datetime(6) DEFAULT NULL,
  `c_timestamp` timestamp NULL DEFAULT NULL,
  `c_time` time(6) DEFAULT NULL,
  `c_year` year(4) DEFAULT NULL,
  `c_char` char(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `c_varchar` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `c_text` text COLLATE utf8mb4_unicode_ci,
  `c_binary` binary(8) DEFAULT NULL,
  `c_varbinary` varbinary(16) DEFAULT NULL,
  `c_blob` blob,
  `c_enum` enum('small','medium','large') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `c_set` set('a','b','c') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `c_json` json DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
